static inline unsigned dongle_bit_count(uint32_t value) {
    unsigned bits=0;
    for (; value; value>>=1) bits+=value&1u;
    return bits;
}
// Value domain from the spec; model gating is separate (dongle_settings.h).
static inline bool dongle_setting_value_valid(uint8_t id, uint32_t value) {
    switch(id) {
        case DONGLE_SETTING_MICROPHONE: return value==0x0u || value==0x1u || value==0x2u;
        case DONGLE_SETTING_EAR_DETECTION: return value==0x2u || value==0x1u;
        case DONGLE_SETTING_LISTENING_MODE: return value==0x1u || value==0x2u || value==0x3u || value==0x4u;
        case DONGLE_SETTING_HOLD_ACTIONS: return value<=0xffffu && ((value&0xffu)==0x1u || (value&0xffu)==0x5u) && (((value>>8)&0xffu)==0x1u || ((value>>8)&0xffu)==0x5u);
        case DONGLE_SETTING_PRESS_SPEED: return value==0x0u || value==0x1u || value==0x2u;
        case DONGLE_SETTING_HOLD_DURATION: return value==0x0u || value==0x1u || value==0x2u;
        case DONGLE_SETTING_HOLD_MODES: return (value&~0xfu)==0 && dongle_bit_count(value)>=2u;
        case DONGLE_SETTING_ONE_BUD_ANC: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_CROWN_DIRECTION: return value==0x2u || value==0x1u;
        case DONGLE_SETTING_TONE_VOLUME: return (value&~0xffu)==0x5000u && (value&0xffu)<=100u;
        case DONGLE_SETTING_SMART_ROUTING: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_SWIPE_DURATION: return value==0x0u || value==0x1u || value==0x2u;
        case DONGLE_SETTING_CALL_CONTROLS: return value==0x300u || value==0x200u;
        case DONGLE_SETTING_VOLUME_SWIPE: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_PERSONALIZED_VOLUME: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_CONVERSATION_AWARENESS: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_ADAPTIVE_STRENGTH: return value<=100u;
        case DONGLE_SETTING_CASE_SOUNDS: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_ALLOW_OFF: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_PAUSE_WHEN_ASLEEP: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_ALLOW_AUTO_CONNECT: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_OPTIMIZED_CHARGING: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_CASE_VOLUME: return value<=100u;
        case DONGLE_SETTING_EN352_PROTECTION: return value==0x1u || value==0x2u;
        case DONGLE_SETTING_GAIN_SWIPE: return value==0x1u || value==0x2u;
        default: return false;
    }
}
// Writable for a known model before any device report.
static inline bool dongle_setting_writable_without_report(uint8_t id) {
    switch(id) {
        case DONGLE_SETTING_MICROPHONE:
        case DONGLE_SETTING_EAR_DETECTION:
        case DONGLE_SETTING_HOLD_ACTIONS:
        case DONGLE_SETTING_HOLD_MODES:
        case DONGLE_SETTING_SWIPE_DURATION:
        case DONGLE_SETTING_CASE_SOUNDS:
        case DONGLE_SETTING_CASE_VOLUME:
            return true;
        default: return false;
    }
}
// Writable while the model is unknown.
static inline bool dongle_setting_writable_with_unknown_model(uint8_t id) {
    switch(id) {
        case DONGLE_SETTING_MICROPHONE:
        case DONGLE_SETTING_EAR_DETECTION:
        case DONGLE_SETTING_LISTENING_MODE:
        case DONGLE_SETTING_HOLD_ACTIONS:
        case DONGLE_SETTING_PRESS_SPEED:
        case DONGLE_SETTING_HOLD_DURATION:
        case DONGLE_SETTING_HOLD_MODES:
        case DONGLE_SETTING_ONE_BUD_ANC:
        case DONGLE_SETTING_TONE_VOLUME:
        case DONGLE_SETTING_SWIPE_DURATION:
        case DONGLE_SETTING_CALL_CONTROLS:
        case DONGLE_SETTING_CASE_SOUNDS:
        case DONGLE_SETTING_OPTIMIZED_CHARGING:
        case DONGLE_SETTING_CASE_VOLUME:
            return true;
        default: return false;
    }
}
